    borderRadius: 2,
    maxHeight: '90vh',
    overflow: 'auto'
  };

  const handleCloseNotification = () => {
    setNotification({ ...notification, open: false });
  };

  const formatCurrency = (value) => {
    if (value === undefined || value === null) {
      return '$0.00';
    }
    const multiplier = costPeriod === 'yearly' ? 12 : costPeriod === 'daily' ? 1/30 : 1;
    return `$${(Number(value) * multiplier).toFixed(2)}`;
  };

  const getDynamoDBDetails = (dynamodb_cost, formData) => {
    const region_multiplier = formData.region === 'us-east-1' ? 1.0 :
                            formData.region === 'us-west-2' ? 1.05 :
                            formData.region === 'eu-west-1' ? 1.12 :
                            formData.region === 'ap-southeast-1' ? 1.15 : 1.0;

    // Constants
    const total_items = formData.scale.total_tenants * formData.scale.endpoints_per_tenant;
    const storage_gb = (total_items * 4) / (1024 * 1024); // 4KB per item
    const daily_writes = networkLoadEnabled ? 
                        networkLoadConfig.messages.events_per_day + networkLoadConfig.api.calls_per_day :
                        1;
    const daily_reads = daily_writes * 2;
    const monthly_writes = daily_writes * 30;
    const monthly_reads = daily_reads * 30;

    // Cost calculations
    const monthly_storage_cost = (storage_gb * 60.48) / 12;
    const write_cost = monthly_writes * 0.00065;
    const read_cost = monthly_reads * 0.00013;
    const base_cost = monthly_storage_cost + write_cost + read_cost;

    return [
      {
        title: 'Storage Cost Calculation',
        items: [
          {
            label: 'Total Items',
            value: total_items.toLocaleString(),
            details: [
              `Number of tenants: ${formData.scale.total_tenants.toLocaleString()}`,
              `Endpoints per tenant: ${formData.scale.endpoints_per_tenant.toLocaleString()}`,
              `Total items = ${formData.scale.total_tenants.toLocaleString()} × ${formData.scale.endpoints_per_tenant.toLocaleString()} = ${total_items.toLocaleString()}`
            ]
          },
          {
            label: 'Storage Size',
            value: `${storage_gb.toFixed(2)} GB`,
            details: [
              'Item size: 4 KB',
              `Total storage = (${total_items.toLocaleString()} items × 4 KB) / (1024 × 1024)`,
              `= ${storage_gb.toFixed(2)} GB`
            ]
          },
          {
            label: 'Monthly Storage Cost',
            value: formatCurrency(monthly_storage_cost),
            details: [
              'Base yearly storage cost: $60.48',
              `Monthly cost = (${storage_gb.toFixed(2)} GB × $60.48) / 12`,
              `= ${formatCurrency(monthly_storage_cost)}`
            ]
          }
        ]
      },
      {
        title: 'Write Operations Cost',
        items: [
          {
            label: 'Daily Write Operations',
            value: daily_writes.toLocaleString(),
            details: [
              `Messages per day: ${networkLoadEnabled ? networkLoadConfig.messages.events_per_day.toLocaleString() : '1'}`,
              `API calls per day: ${networkLoadEnabled ? networkLoadConfig.api.calls_per_day.toLocaleString() : '1'}`,
              `Total daily writes = ${networkLoadEnabled ? 
                `${networkLoadConfig.messages.events_per_day.toLocaleString()} + ${networkLoadConfig.api.calls_per_day.toLocaleString()}` : 
                '1'} = ${daily_writes.toLocaleString()}`
            ]
          },
          {
            label: 'Monthly Write Operations',
            value: monthly_writes.toLocaleString(),
            details: [
              `Daily writes × 30 days`,
              `${daily_writes.toLocaleString()} × 30 = ${monthly_writes.toLocaleString()} operations`
            ]
          },
          {
            label: 'Write Operations Cost',
            value: formatCurrency(write_cost),
            details: [
              'Cost per write request: $0.00065',
              `Monthly cost = ${monthly_writes.toLocaleString()} × $0.00065`,
              `= ${formatCurrency(write_cost)}`
            ]
          }
        ]
      },
      {
        title: 'Read Operations Cost',
        items: [
          {
            label: 'Daily Read Operations',
            value: daily_reads.toLocaleString(),
            details: [
              'Assuming 2 reads per write',
              `Daily reads = ${daily_writes.toLocaleString()} × 2`,
              `= ${daily_reads.toLocaleString()} operations`
            ]
          },
          {
            label: 'Monthly Read Operations',
            value: monthly_reads.toLocaleString(),
            details: [
              `Daily reads × 30 days`,
              `${daily_reads.toLocaleString()} × 30 = ${monthly_reads.toLocaleString()} operations`
            ]
          },
          {
            label: 'Read Operations Cost',
            value: formatCurrency(read_cost),
            details: [
              'Cost per read request: $0.00013',
              `Monthly cost = ${monthly_reads.toLocaleString()} × $0.00013`,
              `= ${formatCurrency(read_cost)}`
            ]
          }
        ]
      },
      {
        title: 'Total DynamoDB Cost',
        items: [
          {
            label: 'Base Cost (Before Region Multiplier)',
            value: formatCurrency(base_cost),
            details: [
              `Storage cost: ${formatCurrency(monthly_storage_cost)}`,
              `Write operations cost: ${formatCurrency(write_cost)}`,
              `Read operations cost: ${formatCurrency(read_cost)}`,
              `Total base cost = ${formatCurrency(monthly_storage_cost)} + ${formatCurrency(write_cost)} + ${formatCurrency(read_cost)}`,
              `= ${formatCurrency(base_cost)}`
            ]
          },
          {
            label: 'Final Cost (After Region Multiplier)',
            value: formatCurrency(dynamodb_cost),
            details: [
              `Base cost: ${formatCurrency(base_cost)}`,
              `Region multiplier (${formData.region}): ${region_multiplier}x`,
              `Final cost = ${formatCurrency(base_cost)} × ${region_multiplier}`,
              `= ${formatCurrency(dynamodb_cost)}`
            ]
          }
        ]
      }
    ];
  };

  const getStorageDetails = (storage) => {
