            ]
          }
        ]
      },
      {
        title: 'Network Data Load Costs',
        items: [
          {
            label: 'Message Publishing', 
            value: formatCurrency(message_publishing_final), 
            details: [
              `Base cost: $${base_cost.toFixed(2)} × 70% = $${message_publishing_base.toFixed(2)}`,
              `After region multiplier (${region_multiplier}x): $${message_publishing_base.toFixed(2)} × ${region_multiplier} = $${message_publishing_final.toFixed(2)} (Monthly message costs)`
            ]
          },
          {
            label: 'API Load', 
            value: formatCurrency(api_load_final), 
            details: [
              `Base cost: $${base_cost.toFixed(2)} × 30% = $${api_load_base.toFixed(2)}`,
              `After region multiplier (${region_multiplier}x): $${api_load_base.toFixed(2)} × ${region_multiplier} = $${api_load_final.toFixed(2)} (Monthly API costs)`
            ]
          },
          {
            label: 'Total', 
            value: formatCurrency(pxgrid_cost),
            details: [
              `Total = Message Publishing + API Load`,
              `$${message_publishing_final.toFixed(2)} + $${api_load_final.toFixed(2)} = $${pxgrid_cost.toFixed(2)}`
            ]
          }
        ]
      }
    ];
  };

  const handleShowDetails = (type, data) => {
    let details;
    let title;

    switch (type) {
      case 'pxgrid':
        details = getNetworkDataLoadDetails(data);
        title = 'Network Data Load Cost Details';
        break;
      case 'storage':
        details = getStorageDetails(data);
        title = 'Storage Cost Details';
        break;
      case 'container':
        details = getContainerDetails(data);
        title = 'Container Infrastructure Cost Details';
        break;
      case 'network':
        details = getNetworkDetails(data);
        title = 'Network Cost Details';
        break;
      default:
